import React from 'react';
import ChatBot from 'react-simple-chatbot';
import { ThemeProvider } from 'styled-components';

const theme = {
  background: '#000',
  fontFamily: 'Arial',
  headerBgColor: '#0dcaf0',
  headerFontColor: '#fff',
  headerFontSize: '1.2rem',
  botBubbleColor: '#0dcaf0',
  botFontColor: '#fff',
  userBubbleColor: '#fff',
  userFontColor: '#000',
};

const steps = [
  {
    id: '1',
    message: 'Merhaba! Sana nasıl yardımcı olabilirim? 😊',
    trigger: 'menu',
  },
  {
    id: 'menu',
    options: [
      { value: 'cv', label: 'CV’mi Göster', trigger: 'cv' },
      { value: 'github', label: 'GitHub Profilim', trigger: 'github' },
      { value: 'iletisim', label: 'İletişim Bilgilerim', trigger: 'iletisim' },
      { value: 'kapat', label: 'Teşekkürler! 😊', trigger: 'kapat' },
    ],
  },
  {
    id: 'cv',
    message: 'CV’mi buradan görüntüleyebilirsin: 📄 https://oguzhanbilgi.github.io/oguzhan-portfolio/cv.pdf',
    trigger: 'menu',
  },
  {
    id: 'github',
    message: 'GitHub profilim burada: 💻 https://github.com/oguzhanbilgi',
    trigger: 'menu',
  },
  {
    id: 'iletisim',
    message: 'Bana şu adresten ulaşabilirsin: 📧 oguzhan-bilgi@hotmail.com',
    trigger: 'menu',
  },
  {
    id: 'kapat',
    message: 'Rica ederim, iyi günler! 👋',
    end: true,
  },
];

const ChatBotBox = () => {
  return (
    <div style={{ position: 'fixed', bottom: '20px', right: '20px', zIndex: 1000 }}>
      <ThemeProvider theme={theme}>
        <ChatBot steps={steps} floating={true} headerTitle="Oğuzhan Destek" />
      </ThemeProvider>
    </div>
  );
};

export default ChatBotBox;
